<div class="page-head"><div><p class="eyebrow">Inventory</p><h1>Low Stock Monitoring</h1><p>Identify products that have reached their reorder level.</p></div></div><section class="panel"><div class="table-wrap"><table class="table"><tr><th>Product</th><th>SKU</th><th>Category</th><th>Current Stock</th><th>Reorder Level</th><th>Status</th></tr><?php foreach($products as $p): ?><tr><td><b><?=e($p['name'])?></b></td><td><?=e($p['sku'])?></td><td><?=e($p['category']??'Uncategorized')?></td><td><?=e($p['quantity'])?></td><td><?=e($p['reorder_level'])?></td><td><span class="badge red"><?=$p['quantity']==0?'Out of stock':'Low stock'?></span></td></tr><?php endforeach; ?><?php if(!$products): ?><tr><td colspan="6" class="empty">Great! No low-stock products right now.</td></tr><?php endif; ?></table></div></section><?php require __DIR__.'/../../../includes/role_footer.php'; ?>
